    res=A.copy()
    def md(S,i,j,metric):
        if S:
            mx=my=None
            best=None
            for x,y in S:
                if metric=='cheb': s=max(abs(i-x),abs(j-y))
                elif metric=='man': s=abs(i-x)+abs(j-y)
                else: s=(abs(i-x)**2+abs(j-y)**2)**.5
                if best is None or s<best: best=s
            return best
        return 99
